window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":221,"source":"خطبه 221.docx","mode":"explicit-parts","parts":["خطبه 221\nبخش اول \nمتن:\nو من كلام له (عليه السلام) قاله بعد تلاوته «أَلْهاكُمُ التَّكاثُرُ حَتَّى زُرْتُمُ الْمَقابِرَ»:\nيَا لَهُ مَرَاماً مَا أَبْعَدَهُ، وَ زَوْراً مَا أَغْفَلَهُ، وَ خَطَراً مَا أَفْظَعَهُ! لَقَدِ اسْتَخْلَوْا مِنْهُمْ أَيَّ مُدَّكِرٍ وَ تَنَاوَشُوهُمْ مِنْ مَكانٍ بَعِيدٍ. أَ فَبِمَصَارِعِ آبَائِهِمْ يَفْخَرُونَ؟ أَمْ بِعَدِيدِ الْهَلْكَى يَتَكَاثَرُونَ؟ يَرْتَجِعُونَ مِنْهُمْ أَجْسَاداً خَوَتْ وَ حَرَكَاتٍ سَكَنَتْ؛ وَ لَأَنْ يَكُونُوا عِبَراً أَحَقُّ مِنْ أَنْ يَكُونُوا مُفْتَخَراً، وَ لَأَنْ يَهْبِطُوا بِهِمْ جَنَابَ ذِلَّةٍ أَحْجَى مِنْ أَنْ يَقُومُوا بِهِمْ مَقَامَ عِزَّةٍ. لَقَدْ نَظَرُوا إِلَيْهِمْ بِأَبْصَارِ الْعَشْوَةِ وَ ضَرَبُوا مِنْهُمْ فِي غَمْرَةِ جَهَالَةٍ؛ وَ لَوِ اسْتَنْطَقُوا عَنْهُمْ عَرَصَاتِ تِلْكَ الدِّيَارِ الْخَاوِيَةِ وَ الرُّبُوعِ الْخَالِيَةِ لَقَالَتْ ذَهَبُوا فِي الْأَرْضِ ضُلَّالًا وَ ذَهَبْتُمْ فِي أَعْقَابِهِمْ جُهَّالًا، تَطَئُونَ فِي هَامِهِمْ وَ تَسْتَنْبِتُونَ فِي أَجْسَادِهِمْ وَ تَرْتَعُونَ فِيمَا لَفَظُوا وَ تَسْكُنُونَ فِيمَا خَرَّبُوا، وَ إِنَّمَا الْأَيَّامُ بَيْنَكُمْ وَ بَيْنَهُمْ بَوَاكٍ وَ نَوَائِحُ عَلَيْكُمْ.\nترجمه:\nشگفتا! چه هدف و مقصد بسيار دورى و چه زيارت کنندگان غافلى و چه افتخار موهوم و نفرت انگيزى (که بر کنار قبور پيشينيان خود مى آيند و به تعداد آنها بر يکديگر تفاخر مى کنند) آنها به سراغ کسانى رفتند که از دسترسشان دورند (و يک عالم ميان آنها فاصله است) آيا به گورها و محل سقوط اجساد پدرانشان افتخار مى کنند يا با شمارش تعداد مردگان، فزونى مى طلبند؟! گويى آنها مى خواهند اجساد بى جان و بدنهاى بى روح و از کار افتاده را باز گردانند (چه خيال باطل و فکر محالى); ولى اگر آن (اجساد بى جان واستخوانهاى پوسيده) مايه عبرت گردد، سزاوارتر است تا مايه تفاخر شود و اگر با توجّه به وضع آنان اين بازماندگان، به آستانه تواضع و ذلت فرود آيند عاقلانه تر است از اينکه آنها را وسيله سربلندى و عزت خود بدانند. (آرى!) اين به جهت آن است که آنها با چشمان کم نور به مردگان خود نگريستند و در درياى جهل و غرور فرو رفتند، اگر شرح حال آنان را از عرصه هاى ويران شده آن ديار و خانه هاى خالى مى پرسيدند در پاسخ به آنها مى گفتند: آنها در زمين گم شدند (و اجسادشان خاک و پراکنده شد); ولى شما از روى جهل همان مسير آنها را ادامه داديد در حالى که از روى جمجمه هايشان عبور مى کنيد و روى اجسادشان زراعت مى نماييد و از آنچه آنها باقى گذاردند مى خوريد و در خانه هاى آنها که رو به ويرانى مى رود سکونت مى گزينيد (شما بر آنها مى گرييد) در حالى که روزهايى که در ميان شما و آنها قرار دارد بر شما مى گريند و نوحه گرى مى کنند!\nتفسیر:\n   کتاب فیض الاسلام ۲۱۱\nموضوع : تکاثر و فخر فروشی\nاز عجیب ترین خطب نهج البلاغه است فضای کلی بر محور مرگ ، مردگان ، شرایط لحظات رفتن از دنیا را ییان می کند.\n(قالَهُ بعدَ تلاوَتِه)\nشان نزول : بعد از تلاوت آیه \n” اَلهیکُمُ التَکاثُر حَتّی زُرتُمُ المَقابِر ” \nشرح خطبه را بیان کردند.\nنکاتی راجغ به آیه : \nزیاده خواهی و جمع اموال شما را به غفلت [الهیکم] واداشته تا به زیارت قبور بروید.\nدو ترجمه متفاوت دارد.\n۱. بسیاری از شارحان با توجه به شان صدور آیه ؛ دو قبیله در فخر فروشی با هم رقابت داشته و مفاخر ، بزرگان، صاحبان قدرت خود را شمرده به یکدیگر مباهات می کردند تا اینکه بسراغ اموات رفته، به شمارش از قبور آنها پرداختند و آنها را جزو خود حساب کرده که تعداد مفاخر آنها بیشتر شود. تا در زندگی دنیایی برای خود جایگاهی ترسیم کنند.\nآیه نازل شد و کار آنان را نفی کرد: کار شما بجایی رسیده که زیارت قبور مردگان و شمارش قیر ها به فخر شما افزوده و از این تفکر نهی شدند.\nمعنای دوم: کثرت گرایی شما را از یاد خدا غافل کرده و اینکار ادامه دارد تا ابنکه مرگ شما فرا رسیده و به قبور خود وارد شوید. زمانیکه سر شما به سنگ لحد خورد شما هوشیار میشوید و می فهمید که تفاخر بد است.\nانچه را که حضرت در این خطبه ذیل آن شرح میدهد در معنای اول است.   \n🔷یا لَهُ مَراماً ما اَبعَدَهُ\nشگفتا ؛ عده ای چه هدف دوری  انتخاب کرده اند. چقدر از کار شما متعجبم !!\nایا این تکاثر ورزی مقصد درستی ست ، خیر کثیر را رها کرده ، تفاخر دنیا را چسبیده اند.\n🔷و زَوراً مااَغفَلَهُ\nشما چه زائران غافلی هستید، در کنار زیارت اهل قبور هم، در غفلت طی میکنید.چقدر خود برتر بینی دارید، بجای تنبه ، انابه ، و عبرت ، در قبرستان هم، دنیای خود را ترویج می دهید.\nقبرستان جایگاه توجه،تذکر و رقت بود .به موسی کلیم خطاب کرد میتوانی مرا در دو جا بیابی‌.《اَنَا عندَ مُنکَسِرَهُ القُلوب و مُندَرِسَهُ القبور》نزد دلهای شکسته و قبرهای کهنه و پوسیده هستم.\nحالت غربت ، تنهایی، وحشت و سنگینی قبرستان شما را بگیرد و یاد من باشید. قبرستان، مکانی برای یادآوری خدا و قیامت که شما از حالت تذکر بیرون آمدید.\nفلسفه رفتن به زیارت اهل قبور، شادی روح اموات و تحت تاثیر قرار گرفتن زندگان است. تا مدرسه آدم سازی باشد.با رفتن به این مکان تغییر و تحول ایجاد شود.  \n🔷و خَطرَاً ما اَفظَعَه\nبزرگ شمردند [خَطَراً]چیزی را که فقط زشتی بود[اَفظعَه]\nاینکه تعدادقبور مردگان خود می شمارید تا به آن فخر کنید ، اصلا جای عزت نیست.زشتی وحقارت است.\n🔷لَقدِ اسْتَخلَوا مِنهم\nبه سراغ کسانی رفتید وعده ای را شمارش میکنید که در بین شما نیستند، جایشان خالی [اِستَخلوا] ولی برای تفاخر آنهارا در زمرهٔ خود بحساب می آورید.\n🔷اَیٌَ مُدٌَکِر\nدر حالیکه به سراغ مردگان رفتن برای عبرت پند و اندرز [مُدّکِر]است. قبور مردگان برای عبرت گیری از حال آنهاست ، اما برای شما سبب فخر دنیوی شده.\n🔷و تَناوَشُوهُم مِن مَکانِِ بَعید\nدسترسی پیدا کرده و طلب کردند [تَناوَشو]مردگان را از مکان دور. در حالیکه  بین مرگ و زندگی فاصله بی نهایتی هست. در دو عالم متفاوت،\nیک عده از قبایل عرب بر سر اموال ، اولاد و داشته های خود را به رخ کشیده و مایه شرافت خود می دانستند.\nتا اینکه به این نتیجه رسیدند در قبرستان قبور طایفهٔ خود را بشمارند.\nقبوری که بیشتر مایه عزت آن فرد میشد.\n تا، بنا بود قبرستان درس عبرت باشد.\n《وَ اَنّی لَهُمُ التَّناوُشُ مِن مَکانِِ بَعید؛  سبا – ۵۲》چگونه از مکان دور انرا بدست خواهند اورد!!\n🔷اَفَبِمُصارِعِ ابائِهِم یَفخَرُون\nآیا انسانهای نادان از محل افتادن [مُصارِع]\nپدران و گذشتگان خود فخر فروشی می کنند!! \nاینقدر ذلیل هستید ، ودلیل عزت و فخر ندارید ، با تعداد مردگان خود از هم برتری می جویید!!\n🔷اَم بِعَدِیدِ الهَلکی’ یَتَکاثَرون\nآیا با تعداد [عَدید]مردگان خود را به هلاکت می اندازند!!\n🔷یَرتَجِعونَ منهم اجساداً خَوَت\nگویا می خواهند اجساد متلاشی شده [خَوَت]در زمین ویران را برگردانند[یَرتَجِعون]در حالیکه هیچگاه نخواهید توانست،  رجعت امکان ندارد که انها را برگردانده وبه کمک خواهی طلب کنید.\n🔷 و حرَکاتِِ سَکَنَت\nگویا بدنهای از حرکت ایستاده را می خواهند به حرکت در آورند. در حالیکه شدنی نیست.آنان در قبر آرمیده و از خود دفاعی ندارند. \n🔷ولَاَن یَکوُنوا عِبُرَاً اَحَقُّ مِن اَن یَکونوا مُفتَخَرا\nاگر زندگان به سبب اموات خود عبرت می گرفتند سزاوارتر بود[اَحقُ] تا با آنان فخر فروشی کنند.\nاین مرام شما مرام زشتی ست که اموات را برای مطامع دنیای خود طلب می کنید.\nاگراین مردگان موجب عبرت باشند، باید بدانید زندگان هم چند صباح دیگر باتمام دارایی و قدرت خود در زیر این خاکها خواهند آرمید.\n سزاوار است که به اموات طایفه خود بنگرید و بترسید ، آماده مرگ شوید و با تمام وجود بپذیرید در شما تغییر ایجاد شده ،مال و فرزند را رها کرده به همین مردگان ملحق خواهید شد، این عبرت گیری موجب افتخار است.\n🔷 وَلَاَن یَهبِطُوا بهم جَنابَ ذلهٕ اَجحیٰ مِن اَن یَقُومُوا بِهِم مَقامَ عِزَّهِِ\nزندگان فرود آیند[یَهبِطوا] به آستانه خضوع و تواضع [ذله] بسبار عاقلانه تر است[اَجحی] تا اینکه حالات مردگان را برای گردنکشی، برتربینی [عزّه] خود بدست اورند.\nاگر به سبب دیدن اهل قبور ، از گردنکشی، تند خویی ، تکبر دست بردارید، درکنارخضوع فرود آیید.عاقلانه  است. اینکه قدرتمندان قبل از شما با آنهمه نیرو و قدرت بدون هیچ مقاومتی سر به زیر خاک برده و منتظر حساب و کتاب خود برزخ را سپری می کنند.براین امر خاضع شوید شرافت و عزت دارد. \n🔷لقد نَظروا الیهِم باَبصارِ العِشوَه\nعلت فخر فروشی  به تعدد قبور ازچشم کم سوی[عِشوَه] شماست.\nبصیرت ندارند از قبر فقط تعداد می دانند ،درون قبر چه خبر است را نمیدانند ، حساب و کتاب ، کوتاهی اعمال ، حسرت و پشیمانی را نمی بینند.\n🔷و ضَربوا منهم فی غَمرهٕ جُهاله\nزندگان در دریای جهالت خود فرو رفته اند. در قبرستان دنیا طلب کردن نشانه نادانی است. \nانسانی که فقط ظاهر بین باشد، در دریای جهل فرو رفته است.\nظاهر بین، بویی ازتقوا نبرده ، چون حقیقت امر را نفهمیده است.\n✳️ رسولخدا صلی الله علیه وآله فرمودند:  چند عامل است که اگر در فرزندان آدم نبود هیچ چیز نمی توانست سر آنان را پایین بیاورد.و به تواضع برساند .\nیک از عوامل مرگ و بیماری است ، ولی انسان با تمام این ناتوانی و مرگ باز هم سرکشی می کند. \nامیرالمومنین فرمود:\nدر ورودی قبرستان بخوانید : \nالسلامُ علی اهلِ لا اله الّا اللّه\nمِن اهلِ لا الهَ الّا اللّه\nبحقِّ لا الهَ الّا الله \nمردگان را قسم بدهید تا بگویند \nکیفََ وجَدتُم قَولَ لا الهَ الا اللّه \nچگونه یافتند.\nدر حکمت ۳۱ فرمود: اگر اموات اجازه و توان داشتند با شما حرف میزدند و بسباری از حقایق را می گفتند.\n \nبنا هست در قبرستان به آنان رسیده تا از این کلمات چیزی دستگیر بشود. صرف رفتن و آمدن و بدون بهره بردن همان کم عقلی و نگاه غیر بصیرتی به قبور است.\n🔷و لَوِ استَنطَقُوا عنهُم عَرَصاتِ تِلکُ الدِّیارِ الخاوِیَه\nاگر از مردگان طلب نطق می کردند [اِستُنطَقوا] از عرصه های خالی وجا مانده او (اموال، ملک، زمینهای کشاورزی که بر سر آنها در دنیا دعوا داشت) اوضاع و احوال او را بپرسند\n🔷والرُّبُوعِ الخالیَهِ لَقالَت:\nاز خانه های [رُبُوع] انباشته خالی و بجا مانده او سوال کنند. مال و حشم او میتوانست سخن بگوید اقرار میکردند به ابنکه : \n🔷دَهَبُوا فِی الاَرضِ ضُلّالاً\nصاحب ما با شدت گمراهی عمر خود تمام کرد. اگر میتوانست سخن بگوید اقرار به یک عمر ضلالت صاحب خود میکرد. \n🔷و‌ذَهَبُتُم فی اَعناقِهِم جُهّالاً\nو اقرار میکردند که شما هم دقیقا همان مسیر انان طی می کنید.[ذَهبتُم] شما هم در جهالت فرو رفتید .\nقبلی با جهل و گمراهی رفت ، شما هم همین مسیر خسارت را پیش گرفتید.\nوای بر شماکه دنباله رو مسیر اشتباه آنها باشید، راه جاهلانه آنان را طی کنید.\n🔷تَطَؤنَ فِی هامِهِم\nاین زمینی که شما طی کرده قدم می زنید[تَطَوُن] جمجمهٔ سر [هام]اموات زیر پای شماست. قدم میگذارید برروی جمجمه مردگان خود.\n« اَفَلم یَهدِ لَهم کَم اَهلَکنا قَبلَهُم مِنَ القُرونِ یَمشونَ فی مَساکَنَهَم  طه – ۱۳۸ »\nآیا هدایت و راهنمایی نشدند ،از اینکه گذشتگان قبل از آنان به هلاکت رسیدند و اکنون در خانه های آنها ساکن شده راه می روند.\n🔷و تَستَثبِتونَ فی اَجسادِهِم\nاز اجساد همین اموات در زمین، گیاهان روییده ، زراعت وکشتزار [تَستَثبِتون] می کنید، برداشت کرده و می خورید. \n🔷 وتَرتَعُونَ فیما لَفَظُوا \nزمینهای قبرستانی تغییر کاربری داده به مزرعه و کشت، خانه و ویلا تبدیل می شود.\nشما بهره بردید از انچه که گذشتگان  پرتاب کرده و جا گذاشتند [لَفَظوا]\n شما جهل داشتیداز آنچه مردگان باقی گذاشته اند. و شما هم میگذارید آیندگان از شما بهره خواهند برد.\n🔷و تَسکُنُونَ فِیما خَرٌَبُوا\n(حال گذشتگان اینگونه است، روزی هم شما اینگونه خواهید بود.)\nشما ساکن شدید در خانه هایی که آنان زندگی کرده و خراب کردند.\nشما خانه نشین خرابه گذشتگانید ولی عبرت نگرفتید.\n« و سَکَنتُم فِی مَساکِنِ الذَینَ ظَلَموا اَنفسَهُم و تَبیَّنَ لَکم کَیفَ فَعَلنا بِهِم و ضَرَبنا لُکمُ الاَمثال؛   ابراهیم – ۴۵ » \nشما ستمکاران در منازل ستمگران سکونت یافتید ، حال برای شما روشن است که با آنها چه کردیم و برای شما مثال زدیم تا عبرت بگیرید. \n🔷 اِنَّمَا الاَیّامُ بَینَکم و بَینَهم بَواکٕ وَ نَوائحُ عَلیکُم \nروز و روزگار بین شما و مردگان، بحال شما گریه [بَواک] و نوحه سرایی [نُوائِح] می کنند که شما هم با همین جهالت و ضلالت از دنیامی روید .\nروزی برای از دست دادن عزیز خود گریه  و نوحه سرایی می کردید.در همانحال روزگار بر شما گریه میکرد.\nبدا به حال شما که نمی فهمید فردا خود شما در همین موقعیت قرار می گیرید .پس بفکر خود، و توشه راه باشید. خود را برای رفتن آماده کنید.چون میهمان بر سفره چیده شده ی خود خواهید بود.\n🔺دو نکته عجیبی ابن ابی الحدید در مورد این خطبه دارد.\n– همانگونه که بعضی آیات قران سجده واجب دارد بعضی از جملات ادبا و فصحا در جمع ادیبان خوانده شود در مقابل کلمات عجیب به سجده می افتند.\nالفاظ این خطبه در اوج فصاحت و بلاغت و چقدر متناسب با حال صحبت کرده\nبه تعبیر ابن ابی الحدید  شنیدن این خطبه ، از جانب ادبا ، شاعران و نویسندگان شایان سجده واجب است.\n🔺نکته دوم : \n– ابن ابی الحدید جمله معاویه را در مدح علی ذکر می کند.\nبا اینکه معاویه دشمن سرسخت  علی بود ولی بعضی جملات را نمی توانست کتمان کند. 《واللّهِ ما ثَنّیَ الفَصاحهِ القَریِش》\nبخدا قسم بنیان گذار بلاغت در قریش علی است ، قریشی که به بلاغت معروف است ، پایه گذار فصاحت آن علی است.\nابی الحدید این جمله را ذکر میکند و میگوید والله من آنرا قبول دارم .\nبه تمام مقدسات عالم قسم از کودکی تا حال بیش از هزار بار این خطبه را خوانده ام و هر بار مطلب جدید ، و تحت تاثیر و ان حالت مرگ در من زنده شده ،  و تمام وجود مرا متوجه مرگ می کند.\nاللهم لا تجعل الدنیا اکبرَ همِّنا","بخش دوم \nمتن:\nأُولَئِكُمْ سَلَفُ غَايَتِكُمْ وَ فُرَّاطُ مَنَاهِلِكُمْ، الَّذِينَ كَانَتْ لَهُمْ مَقَاوِمُ الْعِزِّ وَ حَلَبَاتُ الْفَخْرِ، مُلُوكاً وَ سُوَقاً، سَلَكُوا فِي بُطُونِ الْبَرْزَخِ سَبِيلًا سُلِّطَتِ الْأَرْضُ عَلَيْهِمْ فِيهِ، فَأَكَلَتْ مِنْ لُحُومِهِمْ وَ شَرِبَتْ مِنْ دِمَائِهِمْ، فَأَصْبَحُوا فِي فَجَوَاتِ قُبُورِهِمْ جَمَاداً لَا يَنْمُونَ وَ ضِمَاراً لَا يُوجَدُونَ. لَا يُفْزِعُهُمْ وُرُودُ الْأَهْوَالِ وَ لَا يَحْزُنُهُمْ تَنَكُّرُ الْأَحْوَالِ وَ لَا يَحْفِلُونَ بِالرَّوَاجِفِ وَ لَا يَأْذَنُونَ لِلْقَوَاصِفِ، غُيَّباً لَا يُنْتَظَرُونَ وَ شُهُوداً لَا يَحْضُرُونَ، وَ إِنَّمَا كَانُوا جَمِيعاً فَتَشَتَّتُوا وَ [أُلَّافاً] آلَافاً فَافْتَرَقُوا؛ وَ مَا عَنْ طُولِ عَهْدِهِمْ وَ لَا بُعْدِ مَحَلِّهِمْ عَمِيَتْ أَخْبَارُهُمْ وَ صَمَّتْ دِيَارُهُمْ، وَ لَكِنَّهُمْ سُقُوا كَأْساً بَدَّلَتْهُمْ بِالنُّطْقِ خَرَساً وَ بِالسَّمْعِ صَمَماً وَ بِالْحَرَكَاتِ سُكُوناً، فَكَأَنَّهُمْ فِي ارْتِجَالِ الصِّفَةِ صَرْعَى سُبَاتٍ، جِيرَانٌ لَا يَتَأَنَّسُونَ وَ أَحِبَّاءُ لَا يَتَزَاوَرُونَ. بَلِيَتْ بَيْنَهُمْ عُرَا التَّعَارُفِ وَ انْقَطَعَتْ مِنْهُمْ أَسْبَابُ الْإِخَاءِ، فَكُلُّهُمْ وَحِيدٌ وَ هُمْ جَمِيعٌ وَ بِجَانِبِ الْهَجْرِ وَ هُمْ أَخِلَّاءُ لَا يَتَعَارَفُونَ لِلَيْلٍ صَبَاحاً وَ لَا لِنَهَارٍ مَسَاءً أَيُّ الْجَدِيدَيْنِ ظَعَنُوا فِيهِ كَانَ عَلَيْهِمْ سَرْمَداً؛ شَاهَدُوا مِنْ أَخْطَارِ دَارِهِمْ أَفْظَعَ مِمَّا خَافُوا وَ رَأَوْا مِنْ آيَاتِهَا أَعْظَمَ مِمَّا قَدَّرُوا. [فَكِلَا] فَكِلْتَا الْغَايَتَيْنِ مُدَّتْ لَهُمْ إِلَى مَبَاءَةٍ فَاتَتْ مَبَالِغَ الْخَوْفِ وَ الرَّجَاءِ، فَلَوْ كَانُوا يَنْطِقُونَ بِهَا لَعَيُّوا بِصِفَةِ مَا شَاهَدُوا وَ مَا عَايَنُوا.\nترجمه:\nآنها پيش از شما به کام مرگ که سرنوشت نهايى همه شماست فرو رفتند و قبل از شما به اين آبشخور وارد شدند. همانها که صاحب مقامات عزّت و مرکبهاى افتخار بودند; گروهى سلاطين و گروهى رعايا. (آرى!) آنها همه درون قبرها خزيده اند و زمين در آنجا بر آنها مسلّط شد; از گوشتهايشان خورد و از خونهايشان نوشيد. در حفره هاى گور خويش به صورت جمادى درآمده اند که هرگز نموّى ندارند و ناپيدايانى که اميد يافت شدنشان نيست. حوادث هراس انگيز هرگز آنها را در وحشت فرو نمى برد و دگرگونى حالات، آنان را اندوهگين نمى سازد. به زلزله ها و لرزه ها اعتنايى ندارند و به صداهاى وحشتناک گوش فرا نمى دهند. غايبانى هستند که انتظار بازگشتشان نيست و شاهدانى که هرگز حضور ندارند. آنها جمع بودند و پراکنده شدند و با يکديگر الفت داشتند و جدا گشتند. اگر اخبارشان به دست فراموشى سپرده شده و خانه هايشان در سکوت فرو رفته، بر اثر طول زمان و دورى از محل سکونت نيست، بلکه جامى به آنها نوشانده شده که به جاى سخن گفتن گنگ بودن و به جاى شنوايى کر شدن را به آنها داده و حرکاتشان به سکون مبدّل شده است و در نگاه اوّل گمان مى برى که همگى افتاده اند و به خواب فرو رفته اند (امّا چنين نيست).\nآنان همسايگانى هستند که با يکديگر انس نمى گيرند و دوستانى که به ديدار هم نمى روند. رشته هاى شناسايى در ميان آنها کهنه شده و اسباب برادرى، قطع گرديده است. با اينکه همه جمع اند ولى تنهايند! و با اينکه دوستند از يکديگر دورند! نه براى شب صبحگاهى مى شناسند و نه براى روز، شامگاهى. (آرى!) شب يا روزى که رخت سفر مرگ در آن بسته و از آن کوچ کرده اند براى آنها جاودان خواهد بود. آنها خطرات آن جهان را وحشتناک تر از آنچه مى ترسيدند يافتند و آيات و نشانه هاى (پاداش و ثواب) را بزرگتر از آنچه مى پنداشتند، مشاهده کردند و براى وصول به هر يک از اين دو نتيجه نهايى (بهشت يا دوزخ) تا رسيدن به قرارگاهشان مهلت داده شدند و عالَمى از بيم و اميد براى آنها فراهم ساخته که اگر قادر بر سخن گفتن بودند از وصف آنچه در آنجا (از عذاب الهى) مشاهده کرده اند يا (از نعمتهاى عظيم خداوند) ديده اند عاجز مى ماندند.\nتفسیر:\n  کتاب فیض الاسلام۲۱۱\nموضوع: هشدار از غفلت زدگی ها \nابن ابی الحدید معتزلی می گویداین خطبه را اگر برای فصحا بخوانی در مقابل این خطبه سجده می کنند.همانگونه که قران آیاتی دارد که سجده مستحب و سجده واجب است، این خطبه ایی است که سجده واجب دارد.وجملات دیگری که:  بیش از هزار بار این خطبه را خوانده وهر بار یک مطلب جدیدی، یک تاثیر جدیدی براو گذاشته است. \n🔷أُولَئِکُمْ سَلَفُ غَایَتِکُمْ \nگذشتگان پیش از شما به جایی که مقصدو مرگ [غایت] شماست رخت کشیدند.\nتعبیر امیرالمومنین از مرگ غایت است، سرانجام قطعی همه ما مرگ است.لذا می فرماید: شماباید از این روزنه عبور کنید. مرگ بر پیشانی تک تک شما نوشته شده است.سلف شما به غایت رسیدند شماهم باید به غایتتان که همان مرگ است برسید.\n🔷وَ فُرَّاطُ مَنَاهِلِکُمْ\nزودتر از شما، پیشگامان[فُرّاط] به آبشخور[مناهل] رسیدند.\nبه این چشمه رسیدند، موت را سرکشیدند، ذائقه موت که قران میفرماید همین است، شماهم دنباله رو انها هستید.《کلُ نفسِِ ذائقَهُ المَوت》\nشما هم به زودی باید مرگ را بچشید. \n🔷الَّذِینَ کَانَتْ لَهُمْ مَقَاوِمُ الْعِزِّ\nآنان کسانی بودند که پایه هایی بلند داشتند \n🔷وَ حَلَبَاتُ الْفَخْرِ\nوصاحبان اسبهای فاخر بودند.\n🔷مُلُوکاً وَ سُوَقاً \nپادشاهان و مردم عادی و رعیت\nهمه باید به غایت خودشان برسند.\nاگر شاهی گدایی عاقبت مرگ /\n اگر زرین کلاهی عاقبت مرگ/\nاگر ملک سلیمانت ببخشند/ \nدر آخر خاک راهی عاقبت مرگ/\nهر درجه علمی، اجتماعی، اخلاقی،پولدار، پادشاه، رعیت، همه انها در مسیر مرگ قرار دارند.\n🔷سَلَکُوا فِی بُطُونِ الْبَرْزَخِ سَبِیلًا \nانها در بطنهای برزخ در یک راهی حرکت داده می شوند. [سلَکوا]\nبین شارحین در مورد اینکه منظور حضرت از بطون برزخ چیست دو نظر وجود دارد. ۱- بعضی گویند در اینحا منظورهمان قبر است. چون درروایت داریم. امام صادق فرمود: 《البَرزَخُ قَبر》برزخ همان قبر است. در واقع برزخ ما از قبر شروع می شود وادامه پیدا می کند تا وقتی که قیامت شود.\nپس یک معنی فی بُطُونِ الْبَرْزَخِ سَبِیلًا مردگان داخل قبر یک راه ومسیری دارند که باید طی کنند.\n۲- بعضی گویند: برزخ به معنی برزخ مصطلح است. برزخ در مقابل دنیا، برزخ در مقابل قیامت. \nسه عالم: دنیا، عالم برزخ، عالم قیامت.\nواینکه امیرالمومنین تعبیر بطون را بکار برد، بطون برزخ اشاره می کند به آن اسرار نهفته ای که در برزخ وجود دارد.وما از آن مطلع نیستیم.انها در برزخ حرکت می کنند، ولی برزخ خود عالمی است، اسراری دارد، بطونی ، ویژگیهایی دارد که در دنیا از آن فهمی نداریم. \n🔷سُلِّطَتِ الْأَرْضُ عَلَیْهِمْ فِیهِ \nزمین بر انها مسلط می شود. \n🔷فَأَکَلَتْ مِنْ لُحُومِهِمْ وَ شَرِبَتْ مِنْ دِمَائِهِمْ\nاز گوشت مردگان می خورد.و ازخون مردگان می آشامد. \n🔷فَأَصْبَحُوا فِی فَجَوَاتِ قُبُورِهِمْ جَمَاداً لَا یَنْمُونَ\nوقتی او را در حفره[فَجَوات] قبر می گذارند تبدیل به جماد می شود که رشد ونمو ندارد[لا یَنمُون]\nدر قبرآثار حیات نیست. یکی از آثارحیات رشد ونمو است. کسی که حی است رشد وتغییر می کند. ولی کسی که مرد دیگر آثار حیات ظاهری از او گرفته می شود. \n🔷وَ ضِمَاراً لَا یُوجَدُونَ.\nگمشدگانی [ضِمار]هستند که امیدی به پیدا شدن اینها نیست. \n🔷لَا یُفْزِعُهُمْ وُرُودُ الْأَهْوَالِ \nنه از چیزی بیمناکند. ناراحتی تدارند[لا یُفزِع]\nانسان تا زمانی که روی زمین است نسبت به اتفاقات اطراف موضع می گیرد، ناراحت، خوشحال می شود، می خندد، دلنگرانی پیدا می کند.\nفرمود: وقتی که شما وارد حفره قبر شدید دیگر هیچ اخباری بر شما تاثیر نمیگذارد. سیل، زلزله، روز تولد، روز مرگ تاثیر بر شما ندارد.چون شما از دنیا رفته اید، دل از ان قطع شده . ارتباطی با این طرف ندارید.\n🔷وَ لَا یَحْزُنُهُمْ تَنَکُّرُ الْأَحْوَالِ\nونه از دگرگونیها اندوهناک‌ و احوالات. ناشناخته،است.[تنکر]\n🔷وَ لَا یَحْفِلُونَ بِالرَّوَاجِفِ وَ لَا یَأْذَنُونَ لِلْقَوَاصِفِ\nبه زلزله های تکان دهنده[رواجِف] اعتنا ندارند [یَحفلون]ونه بانگ تندرها را شنوا واز آن ترسان.\n((مرجفه کسانی هستند که با حرفهای انها جامعه ای را متزلزل وبه اضطراب وا می دارد. اراجیف، یعنی حرفهای ناروایی که زده میشودوباعث اضطراب و دلنگرانی می شود. ))\n✅️ اگر چه مردگان نسبت به احوال روی زمین اعتنایی ندارند، نگران ومحزون نیستند، ولی به معنای مطلق نگران نبودن نیست.اتفاقا آنها نگرانند، محزون هستند، دغدغه های مردگان با زندگان، متفاوت است.\nمرحوم کلینی در کافی شریف در باب سوال قبر این روایت را از امام صادق نقل کرده است:\n《یُسألُ المَیِّتُ فی قَبرِهِ عن خَمسٍ : عن صَلاتِهِ ، وزَکاتِهِ ، وحَجِّهِ ، وصیامِهِ ، ووَلایَتِهِ إیّانا أهلَ البَیتِ》\nدر قبر از مرده پنج سؤال مى کنند: از نماز، زکات، حجّ، روزه و ولایتش نسبت به ما خاندان.  \nفرمودند: مومنین وقتی می میرند، نکیر ومنکر از آنها سوال می پرسد.( مَن رَبُّک)، جواب میدهدو هیچ اتفاق ناگواری نمی افتد. ولی از کافر می پرسد( مَن رَبُّک) میگوید: ( لااَدری) نمی دانم. \nروایت است چنان ضرباتی و عذابی به او می دهند که اگر یک صدم آن را بر همه اهل زمین تقسیم کنند هیچ درختی میوه نمی دهد. همه درختها خشک می شود. همه چیز از حالت طبیعی خود خارج می شود. \n🔷غُیَّباً لَا یُنْتَظَرُونَ\nغایبانی هستند که کسی انتظار انان را نمی کشد.\n🔷وَ شُهُوداً لَا یَحْضُرُونَ \nمردگان شاهدانی که حاضر نیستند.\n✅️ البته همه اموات شاهد نیستند. اینکه همه اموات بتوانند برگردندو نظارت داشته باشند نیست. ولی خدا به بعضی از اموات اجازه می دهد که برگردند وبه خانواده و دوستان و اطرافیانشان نگاه کنند. گاهی حاضر هستند ولی شهود آنها از جنس حضور نیست. آنها می بینند، نه اینکه کنار ما باشند و ما آنها را درک‌کنیم. \n🔷وَ إِنَّمَا کَانُوا جَمِیعاً فَتَشَتَّتُوا\nآنها جمع بودند، قوم بودند، وقتی که مردند پراکنده شدند.[شَتَتُوا]\n🔷 وَ آلَافاً فَافْتَرَقُوا؛\nمردگان در دنیا با هم الفت داشتند[الّافاً] وجداگردیدند .\n🔷وَ مَا عَنْ طُولِ عَهْدِهِمْ وَ لَا بُعْدِ مَحَلِّهِمْ \nنه از درازی زمان است [عهدِهم] ونه از دوری مکان \n🔷عَمِیَتْ أَخْبَارُهُمْ\nخبرهاشان پوشیده مانده است.\n  \n🔷وَ صَمَّتْ دِیَارُهُمْ\nوخانه هاشان خموش گردیده.\n🔷وَ لَکِنَّهُمْ سُقُوا کَأْساً بَدَّلَتْهُمْ بِالنُّطْقِ خَرَساً وَ بِالسَّمْعِ صَمَماً وَ بِالْحَرَکَاتِ سُکُوناً\nبلکه جامی[کاساً] به آنان( گناهکاران) نوشاندند( جام مرگ، جام عذاب، ) که گویا بودند ونطق آنان گنگ [خَرَس] گردید، شنوا بودند واز آن پس نشنیدند.جنبنده بودند وآرمیدند. \n 🔷فَکَأَنَّهُمْ فِی ارْتِجَالِ الصِّفَهِ صَرْعَى سُبَاتٍ\nچونان بیهوش به خاک افتادند و خوابیدند.[ارتجال] مانند آنکه یک فکر آنی به ذهن انسان بدون تامل می رسد.\nمرگ وخواب ارتباط دارند.《النَّومُ اَخُ المَوت》خواب برادر تنی مرگ است.\nهنگام خواب ، مرگ و انقطاع روح از جسم راتجربه می کنیم. \n🔷جِیرَانٌ لَا یَتَأَنَّسُونَ\nمردگان با هم همسایه اند اما هیچ انس[یَتاَنسون] والفتی با هم ندارند. \n🔷وَ أَحِبَّاءُ لَا یَتَزَاوَرُونَ\nودوستانی که به دیدار هم نمیروند.\n🔷بَلِیَتْ بَیْنَهُمْ عُرَا التَّعَارُفِ \nرشته های [عُرَا]آشنایی شان پوسیده واز بین رفته است[بَلیت]\n🔷وَ انْقَطَعَتْ مِنْهُمْ أَسْبَابُ الْإِخَاءِ \nپیوندهای برادری شان از هم بریده \n🔷فَکُلُّهُمْ وَحِیدٌ وَ هُمْ جَمِیعٌ\nهمگی با ام جمع هستند اما هر یک  تنهایند. قبرستان، همه جمع هستند ولی هر کدام تنها هستند.\nتک وتنها بودن یکی از ویژگیهای مرگ است. اگر ما اینجا با وحدت وتنهایی و عبادت انس پیدا نکنیم، آنجا اذیت می شویم. \n✅️ اولیای خدا به جایی می رسند که از تنهایی لذت می برند .\nعارفی تک وتنها در اتاق نشسته بود. کسی در زد وارد شد وگفت ما آمدیم شما را از تنهایی درآوریم .عارف گفت: شما آمدید ولی ما قبلا با خدا تنها بودیم‌. تو آمدی جمع ما وخدا را به هم زدی.\n🔷 وَ بِجَانِبِ الْهَجْرِ وَ هُمْ أَخِلَّاءُ \nمردگان از هم دورند، در حالی که رفقای هم بودنر.\nرفاقتهای آنجا جنس دیگری پیدا می کند. دوستی دنیایی در قبر، برزخ وقیامت ادامه پیدا نمی کند.\n✅️ روایات برعکس آن را می گوید: مومنین به زیارت هم میروند .مومنین با همدیگر جلساتی دارند . ولی اینجا حضرت فرمودند : اینجا جای هیچ رفاقتی نیست. در واقع حضرت انسانهای بد، منافقین ، مشرکین را توصیف می کند. یکی از عذابهایی که اهل جهنم می کشند وحدت و تنهایی است. ولی مومنین اجازه دارند به زیارت هم بروند ، به زیارت اهل بیت بروند. به خانواده خود سر بزنند . \n✅️ روزی امیرالمومنین به وادی السلام رفت.( جایی که ارواح مومنین آنجا جمع میشود. و شرافتش به حرم امیر المومنین در نجف است. وبرهوت جایی است که هر منافقی ، مشرکی، گناهکاری را هر جای عالم خاک کنند روح او به برهوت می رود. )\nساعتها سرپا ایستاد ومطالبی را ذکر کرد.راوی میگوید من خسته شده بودم وگاهی نشسته وگاهی ایستادم.\nوقتی حضرت کارش تمام شد سوال کردم باچه کسی حرف میزدیدحضرت فرمودند:《وَ لَو کُشِفَ لَکَ لَرَاَیتَهّم حَلَقا حَلَقا مُحتَبین یَتَحادَثون》 \nبله، اگر پرده‌ها برای تو کنار رود خواهی دید که ارواح مؤمنان در برزخ به صورت حلقه‌وار در حالی که دست‌هایشان را در زانوها حلقه زده‌اند دور هم نشسته‌ و با یکدیگر حرف می‌زنند.\n🔷لَا یَتَعَارَفُونَ لِلَیْلٍ صَبَاحاً وَ لَا لِنَهَارٍ مَسَاءً\nنه برای شب بامدادی می شناسند ، ونه برای روز شامی می دانند. \n🔷أَیُّ الْجَدِیدَیْنِ ظَعَنُوا فِیهِ کَانَ عَلَیْهِمْ سَرْمَداً\nدر هر یک از شب وروز [جدیدین] که رخت بر بسته و کوچ کردند[ظَعَنوا] پیوسته و همیشگی [سرمد] در آنند.\n \n✅️ اینکه امیرالمومنین فرمود برای مردگان شب وروز معنا ندارد ، نکاتی است که شارحین نهج البلاغه به آن توجه کرده اند. یکی از معانی شب وروز نداشتن این است که دیگر تغییر و دگرگونی در مورد آنها معنا ندارد.\nمعنای دوم اینست که مردگان شب وروز ندارند چون انسان تا وقتی که زنده است شبها برای صبح وصبح برای شب برنامه ریزی میکند . در واقع شب و روز برای برنامه ریزی است. ولی کسی که ازدنیا رفته در اختیار خودش نیست هر طور خواست زندگی کند .\nطبق اعمالی که در گذشته انجام داده بود برایش برنامه ای میدهند. باید مسیر خاصی را طی کند . \nمرحوم خویی در منهاج البراعه.( جلد ۱۴ صفحه ۲۲۶)  بحثی را ذکر میکند که ما در قیامت شب و روز نداریم .آنجاهمیشه روز است . \nولی در برزخ شب وروز هست .ایشان به آیاتی از قران وروایات اهل بیت استشهاد می کند . در ذیل آیه ” لَهُم رِزقُهُم فیها بُکره وَ عَشِیا “\nبرای کسانی که از این دنیا رفته اند صبح وشب رزق مخصوصی است. از امام سوال می کنند کجا را میگوید؟ امام صادق فرمود:  ” ذلک فی جنات الدنیا ” رزق داشتن منظور در برزخ دنیایی است. برزخ همان بهشت دنیایی، جهنم دنیایی است. که قبل از قیامت است.\n🔷شَاهَدُوا مِنْ أَخْطَارِ دَارِهِمْ أَفْظَعَ مِمَّا خَافُوا \nخطر خانه هایشان را سخت تر[افظع] از آن دیدند که می ترسیدند.\nمردگان شهادت می دهند.این شهادت اقرار با جان است. شهادتی که حضرت میگوید بالاتر از دیدن است. \n🔷وَ رَأَوْا مِنْ آیَاتِهَا أَعْظَمَ مِمَّا قَدَّرُوا\nونشانه هادیدند بزرگتر ازآنچه می سنجیدند.\n  \n🔷 [فَکِلَا] فَکِلْتَا الْغَایَتَیْنِ مُدَّتْ لَهُمْ إِلَى مَبَاءَهٍ فَاتَتْ مَبَالِغَ الْخَوْفِ وَ الرَّجَاءِ \nاین دو غایت( بهشت وجهنم) که پیش روی انهاست برای آنان به درازا کشید[مُدُّت] تا رسیدن به جایگاه و منزلگاه [مباءَه] در بیم وامید هستند.\n \n🔷فَلَوْ کَانُوا یَنْطِقُونَ بِهَا لَعَیُّوا بِصِفَهِ مَا شَاهَدُوا وَ مَا عَایَنُوا\nاگر می خواستند برای شما آنچه را که دیده اند وشنیده اند توصیف کنند ، انها عاجز میشدند [لَعَیُّوا] ونمیتوانستند بیان کنند‌. \n✅حضرت در خطبه ۱۱۴ فرمود:  \n《 إِنَّهُ لَیْسَ شَیْءٌ بِشَرٍّ مِنَ الشَّرِّ إِلَّا عِقَابُهُ، وَ لَیْسَ شَیْءٌ بِخَیْرٍ مِنَ الْخَیْرِ إِلَّا ثَوَابُهُ، وَ کُلُّ شَیْءٍ مِنَ الدُّنْیَا سَمَاعُهُ أَعْظَمُ مِنْ عِیَانِهِ، وَ کُلُّ شَیْءٍ مِنَ الْآخِرَهِ عِیَانُهُ أَعْظَمُ مِنْ سَمَاعِهِ》\nاز بد، بدترى نیست، مگر کیفر بد آن و از خوب، خوب ترى نیست، مگر پاداش نیک آن. هر چه دنیایى است، شنیدنش بزرگتر از دیدن اوست و هر چه آخرتى است، دیدنش بزرگتر از شنیدن آن است\nاللهم  اجفل عواقب امرنا خیرا","بخش سوم\nمتن:\nوَ لَئِنْ عَمِيَتْ آثَارُهُمْ وَ انْقَطَعَتْ أَخْبَارُهُمْ لَقَدْ رَجَعَتْ فِيهِمْ أَبْصَارُ الْعِبَرِ وَ سَمِعَتْ عَنْهُمْ آذَانُ الْعُقُولِ وَ تَكَلَّمُوا مِنْ غَيْرِ جِهَاتِ النُّطْقِ، فَقَالُوا كَلَحَتِ الْوُجُوهُ النَّوَاضِرُ وَ خَوَتِ الْأَجْسَامُ النَّوَاعِمُ وَ لَبِسْنَا أَهْدَامَ الْبِلَى وَ تَكَاءَدَنَا ضِيقُ الْمَضْجَعِ وَ تَوَارَثْنَا الْوَحْشَةَ وَ [تَهَدَّمَتْ] تَهَكَّمَتْ عَلَيْنَا الرُّبُوعُ الصُّمُوتُ، فَانْمَحَتْ مَحَاسِنُ أَجْسَادِنَا وَ تَنَكَّرَتْ مَعَارِفُ صُوَرِنَا وَ طَالَتْ فِي مَسَاكِنِ الْوَحْشَةِ إِقَامَتُنَا وَ لَمْ نَجِدْ مِنْ كَرْبٍ فَرَجاً وَ لَا مِنْ ضِيقٍ مُتَّسَعاً؛ فَلَوْ مَثَّلْتَهُمْ بِعَقْلِكَ أَوْ كُشِفَ عَنْهُمْ مَحْجُوبُ الْغِطَاءِ لَكَ وَ قَدِ ارْتَسَخَتْ أَسْمَاعُهُمْ بِالْهَوَامِّ فَاسْتَكَّتْ وَ اكْتَحَلَتْ أَبْصَارُهُمْ بِالتُّرَاب، فَخَسَفَتْ وَ تَقَطَّعَتِ الْأَلْسِنَةُ فِي أَفْوَاهِهِمْ بَعْدَ ذَلَاقَتِهَا وَ هَمَدَتِ الْقُلُوبُ فِي صُدُورِهِمْ بَعْدَ يَقَظَتِهَا وَ عَاثَ فِي كُلِّ جَارِحَةٍ مِنْهُمْ جَدِيدُ بِلًى سَمَّجَهَا وَ سَهَّلَ طُرُقَ الْآفَةِ إِلَيْهَا مُسْتَسْلِمَاتٍ، فَلَا أَيْدٍ تَدْفَعُ وَ لَا قُلُوبٌ تَجْزَعُ، لَرَأَيْتَ أَشْجَانَ قُلُوبٍ وَ أَقْذَاءَ عُيُونٍ، لَهُمْ فِي كُلِّ فَظَاعَةٍ صِفَةُ حَالٍ لَا تَنْتَقِلُ وَ غَمْرَةٌ لَا تَنْجَلِي.\nترجمه:\nهر چند آثارشان محو شده و اخبارشان منقطع گشته; ولى چشمان عبرت بين آنان را مى بيند و گوشهاى عقل گفتارشان را مى شنود. (آرى!) آنها سخن مى گويند; ولى نه از طريق زبان، آنها (با زبان حال) مى گويند: چهره هاى خرم و زيباى ما زشت و پژمرده شد و بدنهاى نرم و نازک (که در ناز و نعمت پرورش يافته بود) بر زمين افتاد و از هم متلاشى گشت، لباس کهنگى و فرسودگى بر تن پوشيديم و تنگى قبر، سخت ما را در فشار قرار داد. وحشت و ترس را از يکديگر به ارث برده ايم و خانه هاى خاموش قبر بر ما فرو ريخته است. زيباييهاى بدنهاى ما محو شده و نشانه هاى شناسايى چهره ما دگرگون گشته، اقامت ما در اين خانه هاى وحشت، طولانى شده نه از اين درد و رنج، فرجى يافته ايم و نه از تنگى قبر، گشايشى.\nاگر با عقل خود آنها را در نظر خويش، مجسم سازى يا پرده ها کنار رود و با چشم خود آنها را ببينى در حالى که گوشهاى آنها را حشرات خورده اند و از کار افتاده و بر چشمهايشان سرمه خاک کشيده شده و (در کاسه) فرو رفته، زبانهايى که با سرعت و فصاحت سخن مى گفتند پاره پاره شده، قلبها در سينه هاى آنها پس از بيدارى خاموش گشته و در هر يک از اعضاى آنان پوسيدگى تازه اى آشکار شده و آن را زشت و بدمنظر ساخته و راه آفات را به سوى آن به آسانى گشوده در حالى که همه آنها در برابر اين امور تسليمند. نه دستى براى دفاع وجود دارد و نه قلبى براى جزع و بى تابى (و ناله سر دادن) (آرى اگر حال آنها را در نظر خود مجسم سازى) قلبهايى پر از غم و چشمهايى پر خاشاک را مى بينى (که بر آنها نوحه گرى مى کنند و از همه مصيبت بارتر اينکه) آنها در هر شدت و سختى، حالات ناراحت کننده اى دارند که هرگز دگرگون نمى شود (و به سوى خوبى نمى گرايد) وبلاى فراگيرى دارند که هيچ گاه برطرف نمى گردد.\nتفسیر:\n کتاب فیض الاسلام ۲۱۲ \nموضوع :عبرت گرفتن از حال اموات\nامیرالمومنین صلوات الله علیه در بخشهای قبل فرمود: مردگان برای عبرت گرفتن سزاوارتر هستند تا سبب  فخر فروشی باشند.\nوبه حالات مردگان در برزخ و قبر اشاره فرمود: که اگر بخواهند در مورد شما سخن بگویند زبانشان بسته است و قابل بیان و وصف نیستند.\n“فلو کانوا یَنطقونَ بها لَعَیُّوا بصفهِ ما شاهَدوا “در ادامه فرمود:\n🔷ولَئِن عَمِیَت اثارُهُم \nاگر چه آثار اموات محوشده[عَمیت] واز آنها خبری در دسترس زندگان نیست،ولی آنطور نیست که راهی برای آشنایی با دنیای آنان نباشد.\n🔷وانقَطَعَت اَخبارُهُم \nچشم و گوش جسمانی قادر به خبر گرفتن از آنان نیست ،\n🔷لقَد رَجَعَت فیهِم اَبصارُ العِبَر \n اما چشمهای بصیر و عبرت پذیر به باطن امور می رسند، از آثار محو شدهٔ مردگان عبرت میگیرند.\n🔷و سَمِعُت عنهُم اذانُ العُقُول\nگوش عقل هم می تواند بسیاری از حرفهای انان را بشنود، نه با زبان قال ، بلکه با زبان حال. و از سرگذشت آنها عبرت بگیرد.\n🔷و تَکلَمُوا مِن غیرِ جِهاتِ النُطق\nمردگان ابزار زبان و الفاظ برای سخن گفتن ندارند ولی بازبان حال که دروغی در آن راه ندارد ، با واقعیت و حقیقت تکلم می کنند.\nحالِ کهنگی قبر او فریاد میزند که من هم روزی مثل شما جوان بودم ، پرقدرت بودم ، مال ، زیبایی، سلامت داشتم، ولی الان گرفتار اعمالم هستم.\nابزار دسترسی به احوال مردگان:\n🔷فقالوا: کَلَحَتِ الوُجُوهُ النَواضِر\nاموات با زبان حال میگویند:\nصورتهای زیبا و شاداب [نواضِر] که آرایش و پیرایش داشتیم بعد از مرگ پژمرده شد.[کلَحَت]\nمعنای دوم : حالت پوست و گوشت سوخته (مانند سوزاندن موهای اضافی کله) که به فسیل و جمجمه تبدیل شده.کلَحت گفته میشود.\n🔷و خَوَتِ الاَجسامُ النَواعِم \nجسمهای ناز پروردهٔ ما[نَواعم] بخاک افتاده.[خَوَت]\nمعنای دوم نواعم: تا روح در جسم هست بدن نرم است ولی با خروج روح بدن خشک  میشود. ابدان خشک شده بر زمین افتاده است.\n🔷و لَبِسنا اَهدامَ البِلی\nدر انتقال به دنیای دیگر،لباس فاخر ما به لباس کهنه [بِلا] به کفن تبدیل شد.\n🔷و تَکاءَدَنا ضیقُ المَضجَع \nبه تنگی عذاب قبر [مَضجع]گرفتار و به مشقت افتادیم، [تَکائَد]نه تنها طراوت ما از بین رفت بلکه تنگی و فشار هم بوجود آمد.《ومَن اَعرَضَ عن ذِکرِی فاِنَّ مَعیشَهً ضنکاً؛ طه – ۱۲۴ 》هر کس از ذکر خدا غافل شود با خدا همراه نباشد زندگی سخت و تنگ به او داده میشود.\nبخشی از زندگی در دنیا و بخش دیگر، نمود محنت و رنج ان در قبر است. تنگی و فشار قبر است.\n🔷و تَوارَثنَا الوَحشَهَ\nوحشت ، عذاب و سختی گذشتگان را به ارث بردیم.\nکسانیکه در دنیا می مانند اموال و ملک را به ارث میبرند. اما کسی که از دنیا میرود او هم ارث میبرد ، او رنج، زحمت سختی و تنگی قبر پدران را به ارث میبرد.\n🔷و تَهَکَمَت علینا الرُبُوعُ الصُمُوت\nمردگان با زبان حال بما می گویند:  \nخانه های[ربوع] ساکت و تاریک  قبر،بر ما فرو ریخته و منهدم میشود[تهَکَمت]\nسنگهای فرسوده قبر ،جسم ما را در بر گرفت.چند صباح بعد سنگهای فرسوده فرو ریخته زمین را صاف و تغییر کاربری میدهند و پارک میشود. \n🔷فَانمَحَت مَحاسِنُ اَجسادِنا\n تمام محاسن  و خوبی جسم ما در قبور محو شد[فانمَحَت] و از بین رفت.\nتمام زیبایی مختص به دنیاست.\n🔷و تَنکَرَت مَعارفُ صُوَرِنا\nانچه را که به سبب ان ما را از دیگران متمایز کرده و می شناختند ، شمایل بهم میریزد. \nدرقبور نه تنها محاسن از بین می رود بلکه آن هیبت کلی و ویژگی خاص هر کس از هم می پاشد.\n🔷و طالَت فی مساکِنِ الوحشَهِ اِقامَتِنا \nماندن ما در خانه های وحشت بسیار  طولانی شد.[طالَت]\nخوبی دنیا اینست، هر چه رنج و غم و غصه باشد مدت آن کوتاه است بلاخره تمام میشود.ولی قبر و قیامت ابدیت است و هیچگاه از بین نمیرود.\nپیامبر فرمود: 《ما راَیتُ مَنظَراً اِلّا والقَبر اَفضَعُ مِنهُ》هیچ منظره ای وحشتناکی ندیدم (سیل، زلزله ، آتش سوزی) مگر اینکه قبر از آن وحشتناکتر است.\n🔷ولَم نَحِد مِن کَربِِ فرَجاً،ولا مِن ضَیقِِ مُتَسَعاً\nما در گرفتاری و مشقت هستیم و هیچ امیدی به نجات خود نداریم ، بدترین عذاب است که راه خروج و گشایش نیست.\n《 و تُنذِرُ یومَ الجَمعِ لا ریبَ فیهِ فریقٌ فیِ الجنهِ و فریقٌ فیِ السَعیر  شورا  -۷ 》\nای پیامبر بتو وحی کردیم با این قران مردم را از آن روزی که بدون شک جمع خواهند شد بیم بده ، روزی که گروهی در جنت و گروهی در آتش سوزان دوزخ خواهند بود.\n🔷 حالت تمثیل و تشبیه مردگان درون قبر:\n🔷 و لَو مَثَّلتَهم بعَقلِک اَو کُشِفَ عنهُم مَحجُوبُ الغِطاءِ لَک ،\nای زندگان؛ اگر با عقل ودر ذهن خود مردگان را تمثیل کنید  یا پرده ها کنار رود امان پرده های پنهان مرگ[محجوبُ الغطاء] بالا رود  و حال مردگان دیده شود.\nاحوال آنان راچنین خواهید دید..\nتعبیر لطیفی از پرده پنهان بیان فرموده : پرده گاهی دیده میشود مانند پرده صف جماعت دو گروه از هم متمایز کرده و یکدیگر را نمی بینند اما خود پرده دیده میشود. اما محجوب الغطاء، پرده روی  مرگ قابل رویت نیست.  \nپردا بالا رود احوال مردگان را چنین خواهید دید.\n🔷و قَدِ ارتَسَخَت اَسماعُهُم بِالهَوامِ فَاستَکَّت\nدر گوش آنان حشرات[هوام] رسوخ کرده [اِرتسخَت] گوش کر شده [استکت] طوری لاله گوش از بین رفته  که چیزی بنام گوش باقی نمانده.\n🔷وَاکتَحَلَت اَبصارُهُم \nداخل چشم آنها خاک سرمه کشیده می شود،\n🔷و تَقَطَعَت اَلسِنَهُ فی اَفواهِهِم بعدَ ذَلَقاتِها \n در حیات خود سخنورانی بودند که زبان تیز و برنده [ذلقات] سخنرانی داشتند، که گوشت زبان تکه تکه شده و چیزی از زبان باقی نمی ماند.\n🔷و هَمَدَتِ القُلوبُ فی صُدورِهِم بعدَ یَقضَتِها \nقلبی که در سینه می تپید، ساکن می شود [همَدَت] بعد از اینکه در سینه بیدار بود.[یَقضَتِها] و حرکت داشت کاری از او بر نمی آید\n🔷و عاثَ فی کلِّ جارِحَهِِ منهم جَدیدُ بِلی سَمَجَّها\nتمام اعضا و جوارح فاسد شده [عاثَ] کهنگی و پوسیدگی [بِلی]جدید عارض شده و آنان را زشت و بد منظر کرده [سَمَجَها] از فاسد شدن هم در امان نیستند.\n🔷و سَهَلَّ طُرُقَ الآفَهِ اِلیها \n راه آفت آسان می شود.\nرگ حیات قطع شد ،بدن محل رفت و آمد آفات می گردد.\nدر حیات دنیا آفتهای بیماری را دفع و مداوا می کرد هر گونه آفتی را از خود دفع میکرد و در قبر قادر به دفع حشره ای نیست.\n🔷مُستَسلِماتِِ فلا اَیدِِ تَدفَع، ولا قلَوبُ تَجزَع\nبا آن قدرت و قوت جسم، در برابر کوچکترین حشره تسلیم است.\nدستی ندارد که دفع کند.[لاتَدفَع]\nجانی ندارد که جزع و فزع کند[لاتَجزَع]\n.با فریاد کمک خواهی طلب کند. در برابر هر عذاب و بلایی باید تسلیم باشد. راه مفری نیست.\n« و لَم نَجِد مِن کربٕ فرَجا ولا مِن ضیقٕ مُتَسَعا » راه فرار و فرجی باقی نمانده.\n🔷لَرَاَیتَ اَشجانَ قلوبِِ و اَقذاءَ عیُونِِ\n((لام (لرایت) جزا و جواب شرط است برای جمله (لو مَثَّلتَهم بعَقلِک) لو شرطیه است ، اگر با عقل خود تمثیل کنید.\nبا (لرایت) جواب میدهد ، خواهید دید ))\nبا چشم دل تصور کنید می بینید که قلبها پر درد و سراسر غم[اَشجان] فرا گرفته ، و چشمها از خاشاک[اَقذاء] پر شده ، حال غمناکی دارند.\n🔷لَهم فی کلِّ فَظاعَهِِ صِفهُ حالَهِِ لا تَنتَقِل، وغَمرَهُُ لا تَنجَلِی\n برای اموات در هر لحظه ، لحظات سخت[فَظاعه] و غیر قابل وصف ، حالتی که امکان از بین. رفتن آن حالت وجود ندارد.[لاتَنجلی]\n– چه خبری بالاتر از این ، که باید با چشم عبرت بین نگاه کرد.\n– چه کسی به داد مردگان می رسد جز اعمال خود،\n– دقیقا فردا روزی هم شما دچار چنین حالتی خواهید شد.\n– تا زمانی که هستیم، اعمال از ما دست بر نمیدارد.\n– تا چه زمان هستیم !! سرمدی و ابدی که تاریخ انقضا ندارد.\n– توجه به ابدیت در تربیت انسان بسیار موثر است.\n– توشه ای جمع کنیم که سالیان مدید از آن سفره بهره ببریم.\n– باور بر این قضیه است که اعمال را متفاوت می کند.\n✳️ روایت را مرحوم کلینی در کافی ج۳ ص۲۳۴ نقل کرده: \nامام سید الساجدین فرمود: \nمَا نَدْرِی کَیْفَ نَصْنَعُ بِالنَّاسِ إِنْ حَدَّثْنَاهُمْ بِمَا سَمِعْنَا مِنْ رَسُولِ اللَّهِ ص ضَحِکُوا\nنمیدانم با این مردم چه کنم ، اموری و احادیثی از پیامبر هست برای مردم نقل کنم از باطن حدیث بگویم، تمسخر کرده می خندند\n وَ إِنْ سَکَتْنَا لَمْ یَسَعْنَا\nو اگر نگوییم در حالیکه وظیفه داریم که بگوییم، چون مردم در جهل می مانند.\n فَقَالَ ضَمْرَهُ بْنُ مَعْبَدٍ حَدِّثْنَا\nشخصی بنام ضَمره گفت شما حدیث کنید مشتاییم بدانیم و یاد بگیریم. \n فَقَالَ هَلْ تَدْرُونَ مَا یَقُولُ عَدُوُّ اللَّهِ إِذَا حُمِلَ عَلَى سَرِیرِهِ قَالَ فَقُلْنَا لَا قَالَ فَإِنَّهُ یَقُولُ لِحَمَلَتِهِ\nفرمود: وقتی میت در تابوت گذاشته و حمل می کنید، شما او را ساکت می بینید در حالیکه او فریاد میزند.\n أَ لَا تَسْمَعُونَ أَنِّی أَشْکُو إِلَیْکُمْ عَدُوَّ اللَّهِ خَدَعَنِی وَ أَوْرَدَنِی ثُمَّ لَمْ یُصْدِرْنِی\nاو از دست شیطان و دشمنی او شکایت میکند که او را خدعه زد و مرتکب گناه شد.\n وَ أَشْکُو إِلَیْکُمْ إِخْوَاناً وَاخَیْتُهُمْ فَخَذَلُونِی \nفریاد میزند و از دوستان و رفقایی که تابوت او گرفتند شکایت میکند خیانتها کردند و در جمع انها بخاطر انها مرتکب گناه شدم \nوَ أَشْکُو إِلَیْکُمْ أَوْلَاداً حَامَیْتُ عَنْهُمْ فَخَذَلُونِی \nو از خانواده و اولاد شکایت می کند حامی آنها بودم عمر ، آبرو مال صرف کردم. اما مرا خوار و ذلیل کردند.\nقَالَ فَقَالَ ضَمْرَهُ یَا أَبَا الْحَسَنِ إِنْ کَانَ هَذَا یَتَکَلَّمُ بِهَذَا الْکَلَامِ یُوشِکُ أَنْ یَثِبَ عَلَى أَعْنَاقِ الَّذِینَ یَحْمِلُونَهُ  \nبه این قسمت حدیث که رسید، ضمره پوزخندی زد و  گفت : \nمیت با این کلمات ممکن است از تابوت برخیزد و فرار کند\nقَالَ فَقَالَ عَلِیُّ بْنُ الْحُسَیْنِ ع اللَّهُمَّ إِنْ کَانَ ضَمْرَهُ هَزِئَ مِنْ حَدِیثِ رَسُولِ اللَّهِ ص فَخُذْهُ أَخْذَهَ أَسَفٍ \nامام فرمود: خدایا اگر او حدیث پیامبر را تمسخر کرد ،او را عذاب کن و به او نشان بده.\n قَالَ فَمَکَثَ أَرْبَعِینَ یَوْماً ثُمَّ مَاتَ فَحَضَرَهُ مَوْلًى لَهُ قَالَ فَلَمَّا دُفِنَ أَتَى عَلِیَّ بْنَ الْحُسَیْنِ ع فَجَلَسَ إِلَیْهِ \nچهل روز از این ماجرا نگذشته بود که غلام او نزد حضرت امد \nفَقَالَ لَهُ مِنْ أَیْنَ جِئْتَ یَا فُلَانُ قَالَ مِنْ جِنَازَهِ ضَمْرَهَ  فَوَضَعْتُ وَجْهِی عَلَیْهِ حِینَ سُوِّیَ عَلَیْهِ فَسَمِعْتُ صَوْتَهُ وَ اللَّهِ أَعْرِفُهُ کَمَا کُنْتُ أَعْرِفُهُ\nگفت از تدفین ارباب خود ضمره بر میگردد خطاب به امام گفت :   بعد از اتمام سر به قبر گذاشتم و صدای او را شنیدم ،فریاد میزد حالاتی را که تمسخر کردم دیدم.\n فَقَالَ عَلِیُّ بْنُ الْحُسَیْنِ ع أَسْأَلُ اللَّهَ الْعَافِیَهَ هَذَا جَزَاءُ مَنْ یَهْزَأُ مِنْ حَدِیثِ رَسُولِ اللَّهِ ص.\nامام فرمود: کسی که احادیث ما را تمسخر کند جزای او چنین است.\n✅ نکته عبرت آموزی آن برای ما: \nبعد از مرگ خبرهایی هست، مردگان با زبان شما حرف نمیزنند .\nمانند انسان در خواب و عالم رویا کلی گفتگو میکند و حرف دارد اما شخص بیدار نزدیک او این گفتگو را نفهمیده و نشنیده است.\nبه زبان اموات راه ورود نیست  و بنا نیست چیزی بگویند چون اگر می دانستیم ، بندگی و عبادت از روی ترس و اجبار بود.\nاللهم نعوذ برحمتک من عذابک","بخش چهارم\nمتن:\nفَكَمْ أَكَلَتِ الْأَرْضُ مِنْ عَزِيزِ جَسَدٍ وَ أَنِيقِ لَوْنٍ، كَانَ فِي الدُّنْيَا غَذِيَّ تَرَفٍ وَ رَبِيبَ شَرَفٍ؛ يَتَعَلَّلُ بِالسُّرُورِ فِي سَاعَةِ حُزْنِهِ وَ يَفْزَعُ إِلَى السَّلْوَةِ، إِنْ مُصِيبَةٌ نَزَلَتْ بِهِ ضَنّاً بِغَضَارَةِ عَيْشِهِ وَ شَحَاحَةً بِلَهْوِهِ وَ لَعِبِهِ؛ فَبَيْنَا هُوَ يَضْحَكُ إِلَى الدُّنْيَا وَ تَضْحَكُ إِلَيْهِ فِي ظِلِّ عَيْشٍ غَفُولٍ، إِذْ وَطِئَ الدَّهْرُ بِهِ حَسَكَهُ وَ نَقَضَتِ الْأَيَّامُ قُوَاهُ وَ نَظَرَتْ إِلَيْهِ الْحُتُوفُ مِنْ كَثَبٍ، فَخَالَطَهُ بَثٌّ لَا يَعْرِفُهُ وَ نَجِيُّ هَمٍّ مَا كَانَ يَجِدُهُ وَ تَوَلَّدَتْ فِيهِ فَتَرَاتُ عِلَلٍ آنَسَ مَا كَانَ بِصِحَّتِهِ، فَفَزِعَ إِلَى مَا كَانَ عَوَّدَهُ الْأَطِبَّاءُ مِنْ تَسْكِينِ الْحَارِّ بِالْقَارِّ وَ تَحْرِيكِ الْبَارِدِ بِالْحَارِّ، فَلَمْ يُطْفِئْ بِبَارِدٍ إِلَّا ثَوَّرَ حَرَارَةً وَ لَا حَرَّكَ بِحَارٍّ إِلَّا هَيَّجَ بُرُودَةً وَ لَا اعْتَدَلَ بِمُمَازِجٍ لِتِلْكَ الطَّبَائِعِ إِلَّا أَمَدَّ مِنْهَا كُلَّ ذَاتِ دَاءٍ، حَتَّى فَتَرَ مُعَلِّلُهُ وَ ذَهَلَ مُمَرِّضُهُ وَ تَعَايَا أَهْلُهُ بِصِفَةِ دَائِهِ وَ خَرِسُوا عَنْ جَوَابِ السَّائِلينَ عَنْهُ وَ تَنَازَعُوا دُونَهُ شَجِيَّ خَبَرٍ يَكْتُمُونَهُ. فَقَائِلٌ يَقُولُ هُوَ لِمَا بِهِ وَ مُمَنٍّ لَهُمْ إِيَابَ عَافِيَتِهِ وَ مُصَبِّرٌ لَهُمْ عَلَى فَقْدِهِ يُذَكِّرُهُمْ أُسَى الْمَاضِينَ مِنْ قَبْلِهِ، فَبَيْنَا هُوَ كَذَلِكَ عَلَى جَنَاحٍ مِنْ فِرَاقِ الدُّنْيَا وَ تَرْكِ الْأَحِبَّةِ إِذْ عَرَضَ لَهُ عَارِضٌ مِنْ غُصَصِهِ، فَتَحَيَّرَتْ نَوَافِذُ فِطْنَتِهِ وَ يَبِسَتْ رُطُوبَةُ لِسَانِهِ؛ فَكَمْ مِنْ مُهِمٍّ مِنْ جَوَابِهِ عَرَفَهُ فَعَيَّ عَنْ رَدِّهِ، وَ دُعَاءٍ مُؤْلِمٍ بِقَلْبِهِ سَمِعَهُ فَتَصَامَّ عَنْهُ، مِنْ كَبِيرٍ كَانَ يُعَظِّمُهُ أَوْ صَغِيرٍ كَانَ يَرْحَمُهُ. وَ إِنَّ لِلْمَوْتِ لَغَمَرَاتٍ هِيَ أَفْظَعُ مِنْ أَنْ تُسْتَغْرَقَ بِصِفَةٍ أَوْ تَعْتَدِلَ عَلَى عُقُولِ أَهْلِ الدُّنْيَا.\nترجمه:\nزمين ها، چه بسيار، اجساد نيرومند زيبا و خوش آب و رنگ را که در دنيا نازپرورده و نعمت بودند و پرورش يافته دامان احترام و شرف، در کام خود فرو بردند، همانها که مى خواستند با سرور و خوشحالى غمها را از دل بزدايند و به هنگام فرا رسيدن مصيبت براى از بين نرفتن طراوت زندگى و از دست ندادن سرگرميهاى آن به لذت و خوشگذرانى پناه بردند. (آرى) در آن هنگام که او به دنيا مى خنديد و دنيا نيز در سايه زندگى مرفه و غفلت زا بر او خنده مى زد، ناگهان روزگار خارهاى جانگداز آلام و مصائب را در دل او فرو کرد و گذشت روزگار قواى او را در هم شکست و عوامل مرگ از نزديک به او نظر افکند در نتيجه، غم و اندوهى که هرگز از آن آگاهى نداشت با او در آميخت و غصه هاى پنهانى که حتى خيال آن را نمى کرد در وجودش راه يافت، سُستى بيماريها در او ظاهر شد در حالى که به سلامت و تندرستى، انس شديد داشت. در اين هنگام، هراسان و ترسان به آنچه طبيبان او را به آن، عادت داده بودند پناه برد که حرارت را با برودت، تسکين دهد و برودت را با حرارت تحريک کند; ولى در چنين حالتى هيچ حرارتى را با عوامل برودت فرو ننشاند جز اينکه حرارت شعله ورتر شد و هيچ برودتى را با داروى حرارت زا تحريک نکرد جز اينکه برودت را به هيجان درآورد. براى اعتدال مزاج به هيچ معجونى پناه نبرد جز آنکه به سبب آن، آماده بيمارى ديگرى شد. اين وضع همچنان ادامه يافت تا آنجا که طبيب از درمانش ناتوان شد و پرستارش او را به فراموشى سپرد و خانواده اش از وصف بيمارى او خسته شدند و در پاسخ سؤال کنندگان فروماندند. آنها در کنار بيمار خود نشسته و درباره خبر ناگوارى که تا آن وقت از او مکتوم مى داشتند آشکارا به گفتگو پرداختند. يکى مى گفت او را به حال خود رها کنيد (که رفتنى است) ديگرى آرزوى بازگشت بهبود او را مى کرد و (سومى) آنان را به شکيبايى در فقدانش، دعوت مى نمود و (براى تحمّل اين مصيبت) مصائب و اندوه گذشتگان را به يادشان مى آورد.\nدر اين حال که او در شرف فراق دنيا و ترک دوستان بود، ناگهان عارضه اى گلوگيرش شد که فهم و درک او را ناتوان ساخت و در حيرت و سرگردانى فرو برد و زبانش خشک شد. در اين هنگام به فکر وصايا و سؤالات مهم و لازمى مى افتد که پاسخ آنها را مى دانست; امّا چه سود که زبانش از گفتن بازمانده است، و سخنانى مى شنود که قلب او را به درد مى آورد و مى خواهد جواب آنها را بگويد; امّا قدرت ندارد، از اين رو خود را به ناشنوايى مى زند همان سخنان و زخم زبانهايى که گاه از شخص بزرگى صادر مى شود که اين بيمار او را محترم مى شمرد يا از کوچکى که در گذشته بر او ترحم مى کرده است. (به هر حال) مرگ دشواريهايى دارد که انسان را در خود غرق مى کند، مشکلاتى که هراس انگيزتر از آن است که بتوان در قالب الفاظ ريخت يا انديشه هاى اهل دنيا آن را درک کند.\nتفسیر:\n  کتاب فیض الاسلام ۲۱۲\nشأن صدور خطبه: تفسیری از سوره تکاثر و تاکید بر لزوم عبرت گیری از قبور نه فخر فروشی به آنها. \n🔷فَکَمْ أَکَلَتِ الْأَرْضُ مِنْ عَزِیزِ جَسَدٍ وَ أَنِیقِ لَوْنٍ، \nچه بسیار اجساد عزیز و خوش رنگ و رو[أَنِیقِ لَوْنٍ] که زمین آنها را خورد(از بین برد) . \n🔷کَانَ فِی الدُّنْیَا غَذِیَّ تَرَفٍ وَ رَبِیبَ شَرَفٍ؛ \nهمانهایی که در دنیا غرق در ناز و نعمت[غَذِیَّ تَرَفٍ] و اشراف زاده[رَبِیبَ شَرَفٍ] تربیت شده در خانه های اشرافی بودند. \nمرگ شامل همه ی انسانها می‌شود و تنها امری است که همه به آن اعتقاد دارند و وجودش را کتمان نمی‌کنند (حتی کسانی که به وجود خداوند اعتقادی ندارند هم وجود مرگ را می‌پذیرند) .\nولی متاسفانه علم به این موضوع در بیشتر انسانها عمل را به همراه ندارد:\nیامرگ را پایان زندگی می‌دانیم و آخرت را کتمان میکنیم؛ \n یا مرگ را به قدری از خود دور می‌پنداریم که تاثیری در اعمالمان ندارد و از آخرت غافل می‌شویم. \nحضرت از ما می‌خواهد تا قبرستان ها را بنگریم و از این غفلت بیرون بیاییم\nیکی از ویژگی های بدی که اشراف به آن دچارند در ادامه بیان میشود:\n🔷یَتَعَلَّلُ بِالسُّرُورِ فِی سَاعَهِ حُزْنِهِ\nخود را در هنگام ناراحتی به سرور می‌زند. \nیکی از فلسفه های مصیبت و بیماری این است که موجب تذکر و یادآوری وجود خداوند باشد. \nعده ای هستند که به هنگام بیماری و مصیبت به جای یاد آوری مرگ و آخرت خودشان را با دنیا و مسافرت و… سرگرم می‌کنند تا مبادا لحظه ای با یاد مرگ غفلت را از خود بزدایند. \n🔷 وَ یَفْزَعُ إِلَى السَّلْوَهِ، إِنْ مُصِیبَهٌ نَزَلَتْ بِهِ\nهنگامی که مصیبتی به آنها می‌رسد، به خوشی[سَلوه] پناه می‌آورند. \nفلسفه گرفتاری ها هوشیاری است پس نباید به جای عبرت و درس گرفتن خود را سرگرم کرد و به فراموشی زد. \n🔷 ضَنّاً بِغَضَارَهِ عَیْشِهِ\nدر حالی که به زندگی خوش[غَضَارَهِ] بخل می‌ورزند[ضَنّاً] . \nعلاقه شدیدی به زندگی راحت خود دارند. \n🔷 وَ شَحَاحَهً بِلَهْوِهِ وَ لَعِبِهِ؛\nو علاقه‌ی شدیدی ‌[شَحَاحَهً] به بازی و سرگرمی ها و لهو و لعب زندگی‌شان دارند. \n🔷 فَبَیْنَا هُوَ یَضْحَکُ إِلَى الدُّنْیَا وَ تَضْحَکُ إِلَیْهِ فِی ظِلِّ عَیْشٍ غَفُولٍ\nانسان اشرافی به دنیا می‌خندد و دنیا هم به او میخندد درحالیکه در سایه‌ی عیشی است که او را در غفلتی عجیب فرو برده بود. \nخنده ی دنیا از روی تمسخر است چرا که می‌داند امروز دنیا با تو است ولی می‌رسد زمانی که بر علیه تو می‌شود. \nرفاه زیاد غفلت زا است،علت توصیه به زهد در اسلام هم همین است چرا که رفاه موجب غفلت از یاد خدا و قیامت است.\nخوشی ها ادامه دارد تا زمانی که:\n🔷 إِذْ وَطِئَ الدَّهْرُ بِهِ حَسَکَهُ \nدنیا با خار های تیز و نیش‌هایش [حَسَکَهُ] روی او پا می‌گذارد. \nحسک نوعی تیغ بسیار تیز است همانطور که در کلام حضرت آمده که حاضرم روی خارو خاشاک تیز سعدان(حَسَکِ السَعْدان) بخوابم ولی به کسی ظلم نکنم. \nاگر کسی غافل باشد در یک لحظه دنیا او را لگد مال می‌کند، در حالیکه نیش آن تا عمق جانش فرو می‌رود. \n🔷وَ نَقَضَتِ الْأَیَّامُ قُوَاهُ\nروزگار به مرور قوا و قدرتهای اورا می‌گیرد. \nقوای انسان ثروتمند پول اوست که در هنگام مرگ بر زمین می‌ماند و می‌رود،دیگری قدرتش به جوانی است پس جوانی اش گرفته می‌شود، و دیگری جاه و مقام دارد که از او گرفته می‌شود…..\n🔷 وَ نَظَرَتْ إِلَیْهِ الْحُتُوفُ مِنْ کَثَبٍ، \nمرگ [احُتُوف] از فاصله‌ی نزدیک [کَثَب] به او می‌نگرد. \nانسان عادی وقتی مرگ او می‌رسد متوجه نزدیکی مرگ به خود می‌شود ولی انسان متقی به نزدیکی مرگ واقف است. \n🔷فَخَالَطَهُ بَثٌّ لَا یَعْرِفُهُ \nناگهان حزنی [بَثٌّ] را با خود آمیخته می‌بیند که تا کنون نمیشناخته\nچرا مرگ را نمی‌شناسد و از آمدنش ناراحت می‌شود؟ چون هم مرگ یک پدیده ناشناس است و هم در هنگام سختی ها و مصائب خود را سرگرم کرد و نسبت به یاد مرگ غفلت ورزید تا جایی که الان مرگ برایش امری ناشناخته  است. \nحزن باید در طول زندگی در انسان نهادینه شود تا در موقع مرگ دچار حزن نشویم. پس نباید در طول زندگی از آن فرار کرد و خود را با لهو و لعب سرگرم ساخت. \n🔷وَ نَجِیُّ هَمٍّ مَا کَانَ یَجِدُهُ \nدر او یک نجوایی از غم  وارد می‌شود که تا به حال آن را تجربه نکرده بود. \n🔷وَ تَوَلَّدَتْ فِیهِ فَتَرَاتُ عِلَلٍ آنَسَ مَا کَانَ بِصِحَّتِهِ، \nو در او بیماری و ضعف های متفاوتی[فَتَرَاتُ] متولد می‌شود[تَوَلَّدَتْ] که موجب سستی او می‌شود، در حال که او با سلامتی انس داشت.[آنَسَ] \nانسان اشراف زاده اصلا گمان نمی‌برد روزی بیمار شود و گمان می‌کرد بیماری از آنِ فقرا و همسایه است نه خودش. \n🔷فَفَزِعَ إِلَى مَا کَانَ عَوَّدَهُ الْأَطِبَّاءُ \nپس او به اطباء پناه می‌برد تا آن چیزی که به آن عادت دارد را از آنها بگیرد(یا به معنای دیگر آنچه که اطباء در درمان بیماری ها به آن عادت دارند را از آنها دریافت کند)\n🔷مِنْ تَسْکِینِ الْحَارِّ بِالْقَارِّ وَ تَحْرِیکِ الْبَارِدِ بِالْحَارِّ،\nتا اطباء تب و حرارتش [حارّ]را با سردی تسکین دهند و سردی[بارِد] بدن را با گرمی تحریک کنند.\nوقتی مرگ فرا رسد دارو و درمان هم مؤثر واقع نمیشود:\n🔷 فَلَمْ یُطْفِئْ بِبَارِدٍ إِلَّا ثَوَّرَ حَرَارَهً \n به جای فروکش کردن [یُطْفِئْ] حرارت با سردی، حرارت و گرمی تشدید می‌شود[ثَوَّرَ] \nکسی که مرگش رسیده دارویی که برای پایین آوردن تب و حرارت بدنش به او داده می‌شد و بدن به آن عادت داشت به جای بهبود موجب بیشتر شدن حرارت می‌شود. \n🔷وَ لَا حَرَّکَ بِحَارٍّ إِلَّا هَیَّجَ بُرُودَهً \nو به جای اینکه سردی با گرمی تحریک شود[حَرَّکَ] ، برعکس سردی تشدید می‌شود.[هَیَّجَ] \nدر حاشیه مفاتیح چنین آمده‌:\n «یا مَنْ یَجْعَلُ الشِّفاءَ فیما یَشاءُ مِنَ الاَْشْیاءِ» \nای کسی که شفا را در هر آنچه که بخواهی قرار دادی. \nکسی با یک لیوان آب همه‌ی دردهایش درمان می‌شود و دیگری با داروهای مخصوص که مطابق جسم او ساخته شده و حاصل سالها تلاش و تحقیق دانشمندان است درمان نمی‌شود. چراکه اراده‌ی خدا بر آن تعلق نگرفته. \nگاهی روزه یا بوسه ای که بر تربت سید الشهدا زده می‌شود شفا ولی دوا و دارو پزشکان اثری ندارد. \n🔷وَ لَا اعْتَدَلَ بِمُمَازِجٍ لِتِلْکَ الطَّبَائِعِ إِلَّا أَمَدَّ مِنْهَا کُلَّ ذَاتِ دَاءٍ، \n(وقتی اجل کسی رسیده باشد) ممزوج کردن این طبع ها(سردی و گرمی) باهم نه تنها اعتدالی به وجود نمی‌آورد بلکه دردی دیگر به واسطه آن به وجود می آید. \nانسان چهار طبع دارد سرد و گرم ،خشک و تر.\nاز امام صادق هم روایتی در این زمینه خطاب به طبیب هندی هست که در این مجال نمیگنجد. \nطب سنتی و اسلامی قطعا موثر است ولی نمی‌توان فقط به آن اکتفا کرد و منکر طب جدید شد هر چند طب اسلامی را نمی‌توان طب نامید چرا که بسیار محدود است و همه بیماری ها را شامل نمی‌شود. بلکه یکسری موعظه در زمینه سلامت در روایات آمده است که جامع نیست و اهل بیت به فراخور حال مخاطب و…. بیان داشته اند. \n🔷حَتَّى فَتَرَ مُعَلِّلُهُ \nتا اینکه پزشک معالج[مُعَلِّلُهُ] از او نا امید میشود[فَتَرَ] \n🔷وَ ذَهَلَ مُمَرِّضُهُ\nو پرستارش‌[مُمَرِّضُهُ] از او غفلت میکند[ذَهَلَ]. \nبه سبب نا امیدی و وخامت حال شخص، پرستار او را رها می‌کند و به سایر بیماران رسیدگی می‌کند.\n🔷وَ تَعَایَا أَهْلُهُ بِصِفَهِ دَائِهِ \nخانواده اش از توصیف بیماری[دَائِهِ] او عاجز و ناتوان میشوند[تَعَایَا] \nخانواده اش از بیان بیماری ناتوانند. \n🔷وَ خَرِسُوا عَنْ جَوَابِ السَّائِلینَ عَنْهُ\nنسبت به جواب دادن به کسانی که از حال او می‌پرسند[السَّائِلینَ عَنْهُ] لال و در مانده میشوند[خَرِسُوا] \n🔷 وَ تَنَازَعُوا دُونَهُ شَجِیَّ خَبَرٍ یَکْتُمُونَهُ.\nدر کنار این بیمار در مورد خبر غم انگیزی[شَجیّ] که از او پنهانش کرده‌اند، گفت و گوهایی می‌کنند.[تَنازعوا] \nپشت سر او باهم درگوشی در مورد وخامت حالش صحبت می‌کنند و در مقابل او دلداری می‌دهند و او را به آینده امیدوار میکنند. \n🔷 فَقَائِلٌ یَقُولُ هُوَ لِمَا بِهِ \nیکی از آنهاصراحتا می‌گوید برای او بهبودی نیست بیخود او را امید وار نکنید. \n🔷وَ مُمَنٍّ لَهُمْ إِیَابَ عَافِیَتِهِ\nو دیگری برای سلامتیش دعا می‌کند. \n 🔷وَ مُصَبِّرٌ لَهُمْ عَلَى فَقْدِهِ\nو برخی هم در حالی که آن شخص هنوز زنده است اطرافیانش را دعوت به صبر میکنند.(چرا که گمان می‌کنند کار از کار گذشته.). \n🔷یُذَکِّرُهُمْ أُسَى الْمَاضِینَ مِنْ قَبْلِهِ،\nخاطرات مردگان را که قبل از آنها از دنیا رفته اند را یادآوری می‌کنند. \nبرای تسلی دادن این نکته را متذکر می‌شوند که همه می‌میرند همانطور که قبل از شخص بیمار هم عده‌ای مرده‌اند. \nامیرالمومنین در این جملات بسیار ملموس و دقیق به بیان شرایط و ویژگیهای زمان مرگ میپردازند، تا موجب عبرت و پند ما شود.\n🔷 فَبَیْنَا هُوَ کَذَلِکَ عَلَى جَنَاحٍ مِنْ فِرَاقِ الدُّنْیَا وَ تَرْکِ الْأَحِبَّهِ \nدر همین حال که بیماری طول کشیده بر بال فراق دنیا و ترک آنچه دوست میداریم سوار شده. \nحضرت زندگی در این دنیا را به پرنده ای شبیه می‌داند که سوار بر آنیم تا جایی که پیاده شویم. \n🔷إِذْ عَرَضَ لَهُ عَارِضٌ مِنْ غُصَصِهِ،  \nاینجا است که ناگهان غصه عجیبی به او عارض میشود\nچرا که می‌بیند به ناگاه مرد‌‌.\n🔷فَتَحَیَّرَتْ نَوَافِذُ فِطْنَتِهِ \nهمه آن منافذ زیرکی [فطنتَه] متحیر میشوند. \n🔷وَ یَبِسَتْ رُطُوبَهُ لِسَانِهِ؛\nبه مرور زبان خشک می‌شود.[یبَسَت]\n🔷 فَکَمْ مِنْ مُهِمٍّ مِنْ جَوَابِهِ عَرَفَهُ فَعَیَّ عَنْ رَدِّهِ،\nچه بسیار سؤالات مهمی که جواب همه را می‌داند ولی ناتوان است [فعَیَّ]پاسخ آنها را بدهد. \nامام سجاد هر گاه بیمار میشد (حتی سرما خوردگی) وصیتنامه می‌نوشت و وقتی بهبود میافت می‌فرمود چه کسی بهتر از خودم برای عمل به آن وصیت و فورا اقدام به انجام وصایای خود می‌نمود. \nما هم باید قبل از اینکه قفلی بر دهانمان زده شود به وصیای خود عمل کنیم. و حقوق دیگران را بپردازیم. \n🔷 وَ دُعَاءٍ مُؤْلِمٍ بِقَلْبِهِ سَمِعَهُ فَتَصَامَّ عَنْهُ،\nچه بسیار حرف های دردناکی [مُولِم]که به قلبش اثر می‌گذارد ولی نمی‌تواند پاسخ آنهارا بگوید. [فتَصامَّ]\nجوری خود را به نشنیدن می‌زند که انگار نمی‌شنود. چرا که از پاسخ دادن عاجز است\n🔷 مِنْ کَبِیرٍ کَانَ یُعَظِّمُهُ\nاین سخنان هم از بزرگانی است  که آنها را بزرگ می پنداشت\n🔷 أَوْ صَغِیرٍ کَانَ یَرْحَمُهُ.\nو چه کم سن و سال هایی  که آنها را محترم می‌شمارد ومورد رحم قرار می‌داد. \nکنار دست او جمله ای می گویند که او را آزار میدهد میشنود ولی قادر به پاسخ نیست.\n🔷 وَ إِنَّ لِلْمَوْتِ لَغَمَرَاتٍ هِیَ أَفْظَعُ مِنْ أَنْ تُسْتَغْرَقَ بِصِفَهٍ \nبدانید قطعا برای مرگ سختی هایی هست که این چیزهایی که گفته شد نمی‌تواند آن را توصیف کند. \nاز خود حضرت نقل شده که فرمودند هر آنچه از آخرت برای شما گفتند شنیدنش کمتر از دیدنش است. \nدنیا ظرفیت برزخ و آخرت را ندارد.\n \n🔷أَوْ تَعْتَدِلَ عَلَى عُقُولِ أَهْلِ الدُّنْیَا.\nعجیب تر از آن است که به ذهن مردم دنیا خطور کند. \nدر کافی روایتی است با این مضمون\nجمعی از بنی اسرائیل از کنار قبری پوسیده می‌گذشتند که از خدا خواستند به آنها اجازه داده شود تا با صاحب این قبر سخن بگویند. خدا به آنها اجازه داد تا از صاحب آن قبر سوالاتشان را بپرسند،\nفردی که مردی از مرگ برای ما بگو..\n این شخص گفت من نود و نه سال از تدفینم گذشته ولی درد جان کندن هنوز در بدنم هست. \nالبته مردن و درد مرگ غیر از این دردهای دنیوی است امثال حاج قاسم با شهادت فجیع و دردناکشان و همچنین شهادت حسین بن علی با آن شدت سختی که متحمل شدند ولی مسلما دردی نفهمیدند چرا که شهدا در آن لحظه در  آغوش خداوند خواهند بود. \nبه خدا پناه می‌بریم از سکرات موت."]});
